def compact(a):
    w = 0
    for x in a:
        if x != 0: a[w] = x; w += 1
    a[w:] = [0] * (len(a)-w); return a

def reverse32(n):
    r = int(str(abs(n))[::-1]) * (-1 if n < 0 else 1)
    return r if -(2**31) <= r < 2**31 else None

def extract(data):
    v = data.get('value') if isinstance(data, dict) else None
    return v if isinstance(v, str) else None

def speed(v, actions):
    for delta in actions:
        v = min(10, max(0, v + delta))
    return v
